<?php require_once "../config/database.php";require_once "../includes/functions.php";require_admin();$rows=$pdo->query("SELECT * FROM orders ORDER BY created_at DESC")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Orders</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><?php include "../includes/navbar.php";?><main class="container page"><span class="eyebrow">ADMIN</span><h1>Orders.</h1><div class="table-wrap"><table><tr><th>Order</th><th>User</th><th>Total</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td>#<?=$r["id"]?></td><td><?=$r["user_id"]?></td><td>Rs. <?=number_format($r["total_amount"],2)?></td><td><?=e($r["status"])?></td></tr><?php endforeach;?></table></div></main></body></html>